use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. A request outside the
/// allowlist traps at the boundary, so such URLs are reported as failures here
/// without ever being sent, rather than letting one bad URL fail the whole tick.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lower-cased host of an http(s) URL, or explain why it has none
/// we are willing to request.
fn host_of(url: &str) -> Result<String, &'static str> {
    let rest = if let Some(r) = strip_prefix_ci(url, "https://") {
        r
    } else if let Some(r) = strip_prefix_ci(url, "http://") {
        r
    } else {
        return Err("unsupported URL scheme");
    };

    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    if authority.is_empty() {
        return Err("URL has no host");
    }
    if authority.contains('@') || authority.contains('\\') {
        return Err("URL authority is not a plain host");
    }
    if authority
        .chars()
        .any(|c| c.is_whitespace() || c.is_control())
    {
        return Err("URL authority is malformed");
    }

    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if !port.chars().all(|c| c.is_ascii_digit()) {
                return Err("URL port is malformed");
            }
            &authority[..i]
        }
        None => authority,
    };

    if host.is_empty() {
        return Err("URL has no host");
    }

    Ok(host.to_ascii_lowercase())
}

fn strip_prefix_ci<'a>(s: &'a str, prefix: &str) -> Option<&'a str> {
    let head = s.get(..prefix.len())?;
    if head.eq_ignore_ascii_case(prefix) {
        Some(&s[prefix.len()..])
    } else {
        None
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call, one URL per line.
        state_rw::put("last-input", &subscriptions.urls.join("\n"));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            let target = url.trim();

            match host_of(target) {
                Ok(host) if ALLOWED_HOSTS.contains(&host.as_str()) => {
                    match http_client::fetch(target) {
                        Ok(body) => documents.push(FeedDocument { url, body }),
                        Err(error) => failures.push(FetchFailure { url, error }),
                    }
                }
                Ok(_) => failures.push(FetchFailure {
                    url,
                    error: String::from("host is not in this node's allowlist"),
                }),
                Err(reason) => failures.push(FetchFailure {
                    url,
                    error: String::from(reason),
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
